"use strict";
GUIDE_DATA_EN.sections.push({"id":"g64","part":7,"title":"Solution Design Example","blocks":[{"level":1,"text":"Functional Requirements"},{"level":2,"text":"Business' requested features, such as product features, user interfaces, administration processes, and implementation support or training"},{"level":1,"text":"Nonfunctional Requirements (NFRs)"},{"level":2,"text":"System's attributes that represent its ability to perform, often referred to as the \"ilities\" of software"},{"level":2,"text":"Scalability is a great example of an NFR"},{"level":2,"text":"Examples of NFR"},{"level":2,"text":"Usability"},{"level":2,"text":"How user-friendly it is"},{"level":2,"text":"Scalability"},{"level":2,"text":"How easily a solution can grow or shrink as needs change"},{"level":2,"text":"Availability/Reliability"},{"level":2,"text":"How long it runs within a given time"},{"level":2,"text":"Security"},{"level":2,"text":"How well the solution and the company’s assets are protected"},{"level":2,"text":"Maintainability"},{"level":2,"text":"How easily can it be changed or modified later on"},{"level":2,"text":"Extensibility"},{"level":2,"text":"How easy it is to add new features without altering what is already in place"},{"level":2,"text":"Portability/Compatibility"},{"level":2,"text":"How well the solution works within the existing environment"},{"level":2,"text":"Compliance"},{"level":2,"text":"The need for the solution to comply with relevant legal requirements"},{"level":1,"text":"Employing solution design helps to evaluate the tradeoffs involved"},{"level":1,"text":"In more complex business situations, employ more sophisticated criteria and profiling techniques"},{"level":1,"text":"Functional and non-functional requirements in solution design is really focused on those “ilities” of the software or the thing being built"}]},{"id":"g65","part":7,"title":"Solution Design Approach","blocks":[{"level":1,"text":"Several enterprise environmental factors when creating the solution design"},{"level":2,"text":"Functional requirements"},{"level":2,"text":"Non-functional requirements"},{"level":2,"text":"Constraints"},{"level":2,"text":"Software products"},{"level":2,"text":"Hardware requirements"},{"level":1,"text":"The architect must also acknowledge limitations when designing the system, considering the project's cost, schedule, and scope boundaries as constraints"},{"level":1,"text":"Hardware requirements must be defined and designed in accordance with the company's hardware strategy"},{"level":1,"text":"Environmental factors can impose standard and situational targets, with some factors being temporary or specific to a project too"},{"level":1,"text":"Since solution design involves optimizing the solution, the design team should consider multiple options as well"},{"level":1,"text":"It's essential to balance the time and money invested in the solution design process against the project's benefits"},{"level":1,"text":"The goal of solution design isn't to solve every problem, but to know enough to have confidence that the solution meets the requirements"},{"level":1,"text":"15 Sections of a Solution Design Document"},{"level":2,"text":"Project/Solution Overview"},{"level":2,"text":"This section provides a brief summary of the project or solution that the document covers"},{"level":2,"text":"Intended Audience"},{"level":2,"text":"Clearly identify the intended audience of the document"},{"level":2,"text":"Purpose"},{"level":2,"text":"This section describes how the audience will use the document"},{"level":2,"text":"References"},{"level":2,"text":"This section lists any other documents that the intended audience may need to refer to, such as the project charter or scope statement"},{"level":2,"text":"Glossary"},{"level":2,"text":"Technical documents often contain unfamiliar terms and abbreviations, and this section provides definitions for such terms"},{"level":2,"text":"Current System Summary"},{"level":2,"text":"This section provides a summary of the existing system and its performance or how things are currently being done"},{"level":2,"text":"Detailed Functional Requirements"},{"level":2,"text":"This section clearly describes the business requirements and expectations of the stakeholders, which the team will use to develop tests"},{"level":2,"text":"Non-Functional Requirement Details"},{"level":2,"text":"This section describes the non-functional requirements that the project must meet, such as system performance expectations, against which the team will create tests or requirements"},{"level":2,"text":"Assumptions and Prerequisites"},{"level":2,"text":"This section lists the operating conditions that the team requires and assumes to be in place"},{"level":2,"text":"High-Level Design (HLD)"},{"level":2,"text":"This section includes visual aids, such as process flowcharts and data flow diagrams, to describe the systems and integrations"},{"level":2,"text":"Low-Level Design (LLD)"},{"level":2,"text":"This section provides detailed technical information about all proposed changes to the system"},{"level":2,"text":"Impact Analysis"},{"level":2,"text":"This section evaluates how the proposed solution will impact the existing environment, including any necessary updates or changes that will be required to ensure compatibility"},{"level":2,"text":"Out-of-Scope"},{"level":2,"text":"This section clearly defines the boundaries of the project and what is not included in the solution"},{"level":2,"text":"Risks and Mitigation"},{"level":2,"text":"This section documents known risks and outlines the current mitigation strategy, including any necessary tests or potential unknowns"},{"level":2,"text":"Appendix"},{"level":2,"text":"This optional section includes any supplementary but valuable information that the team may find helpful"},{"level":1,"text":"The template and sections used for HLD and LLD documents can be similar with minor modifications"},{"level":2,"text":"HLD"},{"level":2,"text":"Unlikely to include specific software brand names"},{"level":2,"text":"LLD"},{"level":2,"text":"Highly detailed and provides specific configurations and specifications"}]},{"id":"g66","part":7,"title":"Solution Design in an Agile Project","blocks":[{"level":1,"text":"Solution Design"},{"level":2,"text":"A process that requires thorough documentation"},{"level":2,"text":"In a waterfall approach, it is completed at the beginning"},{"level":2,"text":"In an agile approach, it is completed in each iteration"},{"level":1,"text":"A balanced approach that combines the value of agile and waterfall is recommended"},{"level":1,"text":"Start with NFRs and non-negotiable solution requirements and gradually expand in every iteration"},{"level":1,"text":"User Stories"},{"level":2,"text":"A common format for expressing design requirements in an agile context, while waterfall projects use a single, lengthy document"},{"level":1,"text":"The agile methodology follows iterations that typically last 1-4 weeks (sprint)"},{"level":1,"text":"Agile teams are more self-organized and have a higher performance level than traditional teams"}]},{"id":"g67","part":7,"title":"Diminishing Returns and the Pareto Principle","blocks":[{"level":1,"text":"Law of Diminishing Returns"},{"level":2,"text":"The law of diminishing returns is an economic principle, but it can be applied to many scenarios"},{"level":2,"text":"A small initial investment can lead to a sharp increase in productivity or value"},{"level":2,"text":"Applying the law of diminishing returns to our scenario allows us to identify not the highest possible output, but the highest profitable output"},{"level":2,"text":"In solution design, architects balance multiple requirements to create an optimal solution using diminishing returns"},{"level":1,"text":"Pareto Principle"},{"level":2,"text":"The Pareto principle, also known as the \"80/20 rule\", suggests that 80% of a problem can be solved by addressing 20% of its causes"}]},{"id":"g68","part":7,"title":"IT Infrastructure","blocks":[{"level":1,"text":"The architect responsible for creating the solution design must take into account various IT concepts"},{"level":2,"text":"Computing Models"},{"level":2,"text":"Infrastructure Requirements"},{"level":2,"text":"Security Measures"},{"level":1,"text":"Infrastructure consists of a variety of things"},{"level":2,"text":"Computing Services"},{"level":2,"text":"Encompass all IT infrastructure, including hardware and software, as well as service providers"},{"level":2,"text":"Multi-tiered Architecture"},{"level":2,"text":"A modular software design that breaks software into distinct layers or tiers"},{"level":2,"text":"Modularity is a common non-functional requirement (NFR) that enhances system resilience"},{"level":2,"text":"A single-tier architecture is used in small production and testing environments"},{"level":2,"text":"A three-tier design involves presentation, application, and data"},{"level":2,"text":"Networking and Connectivity"},{"level":2,"text":"Refer to how the various users and components within a system connect"},{"level":2,"text":"It encompasses network configurations, protocols, access rules, and hardware such as cabling, switches, and routers"},{"level":2,"text":"Networking is a crucial component of any software project"},{"level":2,"text":"Storage"},{"level":2,"text":"Physical technology needs a storage plan, including a physical location, temperature control, and humidity control"},{"level":2,"text":"Databases"},{"level":2,"text":"Databases organize electronic information into structured tables that are intentionally designed for ease of retrieval and interpretation by analysts and engineers"},{"level":2,"text":"Data Warehouses"},{"level":2,"text":"A comprehensive database utilized for analytics and reporting purposes"},{"level":2,"text":"It does not perform any action"},{"level":2,"text":"It provides the required data for analysis and reporting"},{"level":2,"text":"The data warehouse process cleans and formats the data"},{"level":2,"text":"Documentation"},{"level":2,"text":"Compromises all the data and diagrams related to the infrastructure"},{"level":2,"text":"Network diagrams"},{"level":2,"text":"Detailed server information"},{"level":2,"text":"Position"},{"level":2,"text":"Service directions"},{"level":2,"text":"Addresses"},{"level":2,"text":"Scripts"},{"level":2,"text":"Protocols"},{"level":2,"text":"Communications"},{"level":2,"text":"Maintenance"},{"level":2,"text":"End-of-life timetables"},{"level":1,"text":"2 Ways to Deliver Computing Services"},{"level":2,"text":"On-premise Computing"},{"level":2,"text":"It is done locally"},{"level":2,"text":"Cloud Computing"},{"level":2,"text":"It requires an internet connection"},{"level":2,"text":"Different Cloud Computing Models"},{"level":2,"text":"Infrastructure as a Service (IaaS)"},{"level":2,"text":"Provides basic computing resources like servers, networks, and storage"},{"level":2,"text":"Platform as a Service (PaaS)"},{"level":2,"text":"Delivers development tools like software environments over an Internet connection"},{"level":2,"text":"Software as a Service (SaaS)"},{"level":2,"text":"A complete software stack that includes infrastructure, environment, and product that end- users would use"},{"level":2,"text":"Anything as a Service (XaaS)"},{"level":2,"text":"Any cloud computing service, where “X’ represents a specific service"},{"level":2,"text":"XaaS refers to the concept of outsourcing a computing a service to a third party"},{"level":1,"text":"Enterprise Resource Planning (ERP)"},{"level":2,"text":"Used by businesses of all types to manage operational workload"},{"level":2,"text":"ERP provides valuable data that can be used to update project progress, such as time allocations"},{"level":1,"text":"Financial System"},{"level":2,"text":"A subset of ERP software that focuses specifically on the financial aspects of an organization"},{"level":1,"text":"Customer Relationship Management (CRM)"},{"level":2,"text":"Designed to establish and maintain customer relationships to enhance revenue and loyalty"},{"level":2,"text":"From a project management standpoint, it is beneficial as it can track trends in complaints and other customer feedback, which can be used to identify areas of focus for new projects or research"},{"level":1,"text":"Electronic Document Management Systems (EDMS) and Record Management Systems (RMS)"},{"level":2,"text":"Companies can create, track, and share documents by automating processes and applying access control"},{"level":1,"text":"Content Management System (CMS)"},{"level":2,"text":"User-friendly systems that simplify complex tasks such as website creation and information management"}]},{"id":"g69","part":7,"title":"Data Classification and Handling","blocks":[{"level":1,"text":"4 Main Categories of Data"},{"level":2,"text":"Public Data"},{"level":2,"text":"Least sensitive and available to anyone"},{"level":2,"text":"Internal Data"},{"level":2,"text":"Accessible to employees within the company and is not public- facing"},{"level":2,"text":"Confidential Data"},{"level":2,"text":"Highly sensitive and has limited access"},{"level":2,"text":"It includes information that’s essential for employees to perform duties"},{"level":2,"text":"Restricted Data"},{"level":2,"text":"Most sensitive type of data where access is restricted and granted only on a need-to-know basis with strict business justification"},{"level":1,"text":"Personally Identifiable Information (PII)"},{"level":2,"text":"Data that can be used to identify an individual"},{"level":2,"text":"Social Security Numbers"},{"level":2,"text":"Email Addresses"},{"level":2,"text":"Passwords"},{"level":2,"text":"Passport Numbers"},{"level":1,"text":"Personal Health Information (PHI)"},{"level":2,"text":"Federally protected in the US under HIPAA regulations, which require organizations to safeguard against unauthorized access and disclosure of sensitive health information"},{"level":2,"text":"PHI is a combination of PII and health information"},{"level":2,"text":"PII"},{"level":2,"text":"Person’s identity"},{"level":2,"text":"PHI"},{"level":2,"text":"Health information"},{"level":1,"text":"General Data Protection Regulation (GDPR)"},{"level":2,"text":"European Union (EU) data privacy and security law that encompasses 11 chapters of regulations and is considered the strictest privacy law"},{"level":1,"text":"Data privacy laws provide protection to consumers in their own jurisdiction"},{"level":1,"text":"Non-compliance with regulations has negative repercussions for both individuals and companies"},{"level":1,"text":"Intellectual Property (IP)"},{"level":2,"text":"Creations of the mind that serve as assets in business"},{"level":2,"text":"4 Types of IP Assets"},{"level":2,"text":"Patents"},{"level":2,"text":"Copyrights"},{"level":2,"text":"Trademarks"},{"level":2,"text":"Trade Secrets"},{"level":2,"text":"A unique category of intellectual property that can provide a company with a competitive edge"},{"level":1,"text":"Branding Restrictions"},{"level":2,"text":"A company may have a logo that is trademarked and permitted for use on its documents and products"},{"level":2,"text":"The company can limit where the logo is positioned on a page and which document types can include it"},{"level":2,"text":"The company may create templates for different document types"}]},{"id":"g70","part":7,"title":"Operational Security","blocks":[{"level":1,"text":"Digital and operational security are paramount for protecting sensitive information"},{"level":1,"text":"It is important to grant access to project team members and stakeholders with the least privilege required"},{"level":1,"text":"Access levels of the products added to a solution design should meet the requirements"},{"level":1,"text":"Establish a remote access policy that defines who can connect to the network and how"},{"level":1,"text":"Employ multi-factor authentication to secure systems"},{"level":1,"text":"Multi-Factor Authentication (MFA)"},{"level":2,"text":"Enhances security by requiring users to provide at least two pieces of evidence to access a remote system or resource"},{"level":2,"text":"The process involves two or more credentials, which fall under three categories:"},{"level":2,"text":"Something you know"},{"level":2,"text":"Something you have"},{"level":2,"text":"Something you are"},{"level":2,"text":"MFA is commonly used by companies to access their network, with employees having to enter a password and scan a smart card to log into their computer at work"},{"level":1,"text":"Operational Security (OPSEC) brings people and the physical environment into security equation"},{"level":2,"text":"Removable Media"},{"level":2,"text":"Removable media, like USB drives, provide users with a convenient way to store and transfer files between computers"},{"level":2,"text":"They also pose a significant security risk as they can be easily copied or moved"},{"level":2,"text":"To mitigate this risk, companies may restrict the use of removable media and implement security policies such as USB management that logs all connections and may block the use of removable media"},{"level":2,"text":"Mobile Devices"},{"level":2,"text":"Mobile devices have become an increasingly popular way for employees to access corporate applications and data"},{"level":2,"text":"It creates additional security risks as company assets can be accessed from a variety of locations"},{"level":2,"text":"To address this, companies may issue corporate devices and require the use of mobile device management (MDM) software, which enables IT functions to monitor and remotely erase compromised devices"},{"level":2,"text":"Facility Access"},{"level":2,"text":"Unauthorized access to company facilities can lead to theft of assets or compromise of networks too"},{"level":2,"text":"To prevent this, companies restrict facility access to authorized users only"},{"level":2,"text":"This helps to ensure that company assets, including computers, mobile devices, and documents, are secured and protected"},{"level":2,"text":"Background Screening"},{"level":2,"text":"If your project involves handling information related to national defense or foreign relations, it is considered national security information in the United States"},{"level":2,"text":"Access to this information is highly restricted, and it should receive the highest sensitivity classification"},{"level":2,"text":"National Security Information or Clearance Requirements"},{"level":1,"text":"Individuals who need to access this information must pass a clearance and credit investigation to obtain authorization, similar to a very in-depth background check"},{"level":1,"text":"4 Clearance Levels"},{"level":2,"text":"Confidential"},{"level":2,"text":"Secret"},{"level":2,"text":"Top Secret"},{"level":2,"text":"Sensitive Compartmented Information (SCI)"},{"level":1,"text":"The clearance requirement for the project is mandated by the nature of the information being handled Managing Resources"}]},{"id":"g71","part":8,"title":"Managing Resources","blocks":[{"level":1,"text":"Resource management is a crucial aspect of project management and encompasses the planning phase through the closing phase of the project"},{"level":1,"text":"The PM is responsible for contributing to the professional development of team members"},{"level":1,"text":"Resources, both physical and human, go through a four-phase life cycle"},{"level":2,"text":"Acquisition"},{"level":2,"text":"Maintenance"},{"level":2,"text":"Improvement"},{"level":2,"text":"Retirement"},{"level":1,"text":"Succession Planning"},{"level":2,"text":"Crucial to identify potential replacements for critical roles, promote career development, and ensure knowledge transfer and resiliency within the organization"},{"level":1,"text":"Project managers play a crucial role in acquiring the necessary resources to successfully complete a project"},{"level":2,"text":"These resources include financial support and tangible assets"},{"level":1,"text":"Insufficient resources can lead to a stressful experience for the team and increase the likelihood of project failure"},{"level":1,"text":"By following a structured needs assessment process, project managers can create a balanced resource plan that ensures the project's success"},{"level":1,"text":"Gap analysis is a flexible approach that aims to investigate the causes of gaps and potential solutions, using tools such as the fishbone diagram, skills matrix, and histogram"},{"level":1,"text":"Resource management in project management involves five key steps"},{"level":2,"text":"Estimating necessary resources"},{"level":2,"text":"Securing the resources"},{"level":2,"text":"Training team members"},{"level":2,"text":"Allocating resources to tasks"},{"level":2,"text":"Monitoring and adjusting resources"}]},{"id":"g72","part":8,"title":"Types of Resources","blocks":[{"level":1,"text":"Project managers need to acquire, manage, and decommission resources"},{"level":1,"text":"It is essential to understand the difference between human, physical, and capital resources throughout the project management process"},{"level":1,"text":"Human resources encompass the time, skills, and knowledge of individuals applied towards project tasks"},{"level":1,"text":"Physical resources are the goods needed to support a project"},{"level":2,"text":"Equipment"},{"level":2,"text":"Software"},{"level":2,"text":"Office Supplies"},{"level":2,"text":"Workspaces"},{"level":2,"text":"Buildings"},{"level":2,"text":"Vehicles"},{"level":1,"text":"Money is referred to as capital resources, which include the funding required to carry out a project, encompassing team and project budgets and long-term investment possibilities"},{"level":1,"text":"Managing the budget is critical to project management"}]},{"id":"g73","part":8,"title":"Resource Sourcing and Allocation","blocks":[{"level":1,"text":"Origin of resources is determined by the sourcing method"},{"level":1,"text":"Internal refers to resources that are within the company's possession or that will be acquired by the company"},{"level":2,"text":"Internal resources are less available but more affordable than external resources"},{"level":1,"text":"External refers to resources that the company does not possess and has no intention of purchasing outside of the project's scope"},{"level":2,"text":"External resources are more available but more expensive"},{"level":1,"text":"Scheduling internal resources can be difficult because they are often shared services"},{"level":1,"text":"Evaluating vendors early in the procurement process can save time and effort"},{"level":1,"text":"Projects with high priority are more likely to receive internal resources on their preferred schedule, but they do not control all resource allocations"},{"level":1,"text":"Highly critical resources are more likely to require external sourcing when an internal option is unavailable"},{"level":1,"text":"If a project requires external resources, it is a need to develop a procurement plan"},{"level":2,"text":"During the early planning stages, conduct a preliminary needs assessment and create a high-level procurement plan"},{"level":2,"text":"Needs Assessment"},{"level":2,"text":"Structured process for identifying the goods and services required to solve the project’s problem"},{"level":2,"text":"Procurement Plan"},{"level":2,"text":"Serves as the business case for using external resources and outlines a strategy for finding and managing vendors"},{"level":2,"text":"Preliminary Plan"},{"level":2,"text":"May have less detail, but will continue to be refined throughout the project"},{"level":1,"text":"The procurement plan may include the following details:"},{"level":2,"text":"An overview of the required goods or services"},{"level":2,"text":"Delivery and implementation dates"},{"level":2,"text":"Critical dates"},{"level":2,"text":"Analysis of the financial and risk impact of procuring these resources"},{"level":2,"text":"Contract types"},{"level":2,"text":"Evaluation methods"},{"level":2,"text":"Vendor performance metrics"},{"level":2,"text":"Available vendor options"},{"level":2,"text":"Detailed financial analysis"},{"level":1,"text":"Developing a procurement plan can improve the project's outcomes"},{"level":1,"text":"All resources are either dedicated or shared and the allocation method describes how a resource's time or capacity is spent during a project"},{"level":2,"text":"A dedicated resource will not guarantee a maximum capacity"},{"level":2,"text":"Dedicated resources are useful when a project requires specialized skills or equipment"},{"level":2,"text":"Shared resources are a better choice when the skill level required is lower or when resources are scarce"}]},{"id":"g74","part":8,"title":"Calculating Shared Resource Capacity","blocks":[{"level":1,"text":"Shared resources’ capacity is divided among multiple projects"},{"level":1,"text":"Steps in Calculating Shared Resource Capacity"},{"level":2,"text":"Identify the total hours and overhead hours"},{"level":2,"text":"Subtract the overhead time from the total time to calculate the available time"},{"level":2,"text":"Total Time – Overhead Time = Available Time"},{"level":2,"text":"Divide available time by the number of projects to determine how much time they can spend per project"},{"level":2,"text":"Available Time / Number of Projects"},{"level":2,"text":"Allocate time"},{"level":1,"text":"Knowing how to calculate capacity will be helpful in preparing for any situation"},{"level":2,"text":"Overestimating availability can cause project delays"}]},{"id":"g75","part":8,"title":"The Resource Lifecycle","blocks":[{"level":1,"text":"4 Phases of Resource Lifecycle"},{"level":2,"text":"Acquisition"},{"level":2,"text":"The company procures goods and hires people based on the needs assessment process initiated by the project manager"},{"level":2,"text":"Once acquired, resources require regular maintenance"},{"level":2,"text":"Repairs"},{"level":2,"text":"Upgrades"},{"level":2,"text":"Inventory Tracking"},{"level":2,"text":"Security Patches"},{"level":2,"text":"System Updates"},{"level":2,"text":"Work Schedules"},{"level":2,"text":"Motivation"},{"level":2,"text":"Support"},{"level":2,"text":"Performance Feedback"},{"level":2,"text":"Maintenance"},{"level":2,"text":"Resources receive operational support to function effectively"},{"level":2,"text":"Improvement"},{"level":2,"text":"Involves enhancing equipment, software, and employee performance"},{"level":2,"text":"Retirement"},{"level":2,"text":"Requires advance notice to prepare for a replacement"},{"level":2,"text":"Three things should come to mind when we discuss resource retirement"},{"level":2,"text":"End of Life (EOL) Software"},{"level":2,"text":"Software reaching its end of life (EOL) is a common issue for companies"},{"level":2,"text":"EOL means the vendor will no longer provide updates or support for the software after a specified date"},{"level":2,"text":"Security patches are no longer available for EOL software"},{"level":2,"text":"EOL notices are a sign to begin decommissioning the product and finding a replacement"},{"level":2,"text":"Hardware Decommissioning"},{"level":2,"text":"Companies often keep extra IT equipment like laptops and headsets in stock, and multiple servers in different locations for failover protection"},{"level":2,"text":"Use cloud storage to effectively outsource server distribution"},{"level":2,"text":"During decommissioning, IT staff initiate a new life cycle to acquire IT infrastructure"},{"level":2,"text":"Succession Planning"},{"level":2,"text":"A proactive approach where companies develop a plan for identifying potential replacements for critical roles that become vacant"},{"level":2,"text":"It is when the employees leave their positions"},{"level":2,"text":"Employees may leave their positions, either by moving to another company or transitioning to a different role within the same organization"},{"level":2,"text":"Succession planning identifies the necessary knowledge, skills, and responsibilities for the position, and documents the processes involved"},{"level":2,"text":"It helps preserve company knowledge and increases resiliency by eliminating a single point of failure"}]},{"id":"g76","part":8,"title":"Conduct a Needs Assessment","blocks":[{"level":1,"text":"PMs need to acquire enough resources to complete the project"},{"level":1,"text":"Underutilization can be as big of a problem as overutilization sometimes"},{"level":1,"text":"Needs Assessment"},{"level":2,"text":"Identifies the resources required by a project to solve a business problem"},{"level":2,"text":"These resources can include skills, software, equipment, and other tangible and intangible assets"},{"level":2,"text":"Needs assessment should be intentional and structured"},{"level":1,"text":"Conducting a thorough needs assessment can offer several benefits, including the early identification of gaps, allowing the team to consider multiple options"},{"level":2,"text":"It can improve on-time performance"},{"level":1,"text":"4 Steps in Conducting a Needs Assessment"},{"level":2,"text":"Understanding the project’s requirements"},{"level":2,"text":"Project Objective"},{"level":2,"text":"Success Criteria"},{"level":2,"text":"Milestones"},{"level":2,"text":"Deliverables"},{"level":2,"text":"Identifying the current resources"},{"level":2,"text":"Take a broad look at your resource pool, including specific team members, software, and equipment"},{"level":2,"text":"Identifying any resources gaps"},{"level":2,"text":"Compare your future state and current state summaries to identify any resource gaps"},{"level":2,"text":"Addressing gaps"},{"level":2,"text":"Create a plan to address each identified gap and put it into action"},{"level":1,"text":"This assessment will enable us to identify areas that require improvement and provide a clear roadmap towards their cloud adoption journey"}]},{"id":"g77","part":8,"title":"Gap Analysis","blocks":[{"level":1,"text":"Gap analysis compares the current and future states to identify and describe differences"},{"level":1,"text":"Skill Gap Analysis"},{"level":2,"text":"Identifies the required skills that are currently unavailable within the team"},{"level":1,"text":"Skill requirements are typically measured by two criteria"},{"level":2,"text":"Type"},{"level":2,"text":"Refers to the specific skills required to complete the task, such as graphic design, project management, or a specific coding language"},{"level":2,"text":"Expertise"},{"level":2,"text":"Refers to the level of competency required, such as novice, competent, and expert"},{"level":1,"text":"Feature and Function"},{"level":2,"text":"Capabilities and tasks that physical resources will be able to perform"},{"level":2,"text":"Functions"},{"level":2,"text":"Specific tasks or executions"},{"level":2,"text":"Features"},{"level":2,"text":"Tools to enable functions"},{"level":2,"text":"To resolve any gaps in features and functions, adjustments to configurations, requirements, and plans may be necessary"},{"level":1,"text":"Resource Utilization"},{"level":2,"text":"Measures the effectiveness of project resources"},{"level":2,"text":"A resource is considered underutilized if the utilization percentage is below 100%, while overallocation occurs when the percentage exceeds 100%"},{"level":1,"text":"Time Allocated"},{"level":2,"text":"Total amount of time that a resource is scheduled to work on any task within the project"},{"level":1,"text":"Total Time Available"},{"level":2,"text":"Total amount of time a resource is available to work on the project"},{"level":1,"text":"The utilization gap occurs when the actual resource utilization percentage differs from the desired or target utilization percentage"},{"level":2,"text":"One possible cause of the underutilization gap could be the lack of clear task priorities, leading to inefficient task allocation"},{"level":2,"text":"Another cause could be the team's lack of necessary skills to complete tasks, resulting in delays and underutilization"},{"level":2,"text":"Utilization gaps can significantly impact project outcomes"}]},{"id":"g78","part":8,"title":"Resource Optimization","blocks":[{"level":1,"text":"Resource optimization techniques can be employed during the planning and execution phases of a project"},{"level":1,"text":"2 Primary Techniques of Resource Optimization"},{"level":2,"text":"Resource Smoothing"},{"level":2,"text":"Minimizes the fluctuation of resource utilization across different time periods"},{"level":2,"text":"Resource smoothing is effective in streamlining projects that are on schedule but have irregular scheduling"},{"level":2,"text":"Smoothing creates an even workload from week to week, but it doesn't allow the end date to shift"},{"level":2,"text":"Resource Leveling"},{"level":2,"text":"Optimization strategy that minimizes fluctuations and permits the extension of a project timeline"},{"level":2,"text":"Leveling will rearrange work until nobody is overutilized, but it could extend the project's end date"}]},{"id":"g79","part":8,"title":"Common Diagrams","blocks":[{"level":1,"text":"Gap analysis aims to investigate the causes of gaps and potential solutions"},{"level":1,"text":"Fishbone Diagram"},{"level":2,"text":"Also known as an Ishikawa or Cause and Effect Diagram, helps to visualize how different factors impact a single outcome"},{"level":2,"text":"Any category grouping that works for the project can be used, such as the Work Breakdown Structure (WBS) in project management or the standard category set known as the 6Ps"},{"level":2,"text":"6 Ps"},{"level":2,"text":"Policy"},{"level":2,"text":"Process"},{"level":2,"text":"People"},{"level":2,"text":"Plant Program"},{"level":2,"text":"Product"},{"level":1,"text":"Skills matrix is useful for identifying development areas"},{"level":2,"text":"Identify all the skills necessary for a project and record them on the matrix"},{"level":2,"text":"Each team member assesses their competency level for each skill"},{"level":1,"text":"Histogram"},{"level":2,"text":"A type of column chart frequently used in statistical analysis"},{"level":2,"text":"PMs can use histograms to summarize large datasets, evaluate processes, and track resource utilization over time"}]},{"id":"g80","part":8,"title":"Resource Management Process","blocks":[{"level":1,"text":"Resource management steps are not necessarily sequential"},{"level":1,"text":"Resource Management Process"},{"level":2,"text":"Estimate the necessary resources"},{"level":2,"text":"This requires conducting a needs assessment to determine the human and physical resources needed to complete the project's deliverables"},{"level":2,"text":"Secure the resources"},{"level":2,"text":"This involves completing a gap analysis to determine which resources are unavailable and creating a plan to acquire the necessary resources"},{"level":2,"text":"This may include purchasing physical resources, restocking consumables, procuring equipment, or hiring external services"},{"level":2,"text":"Train team members"},{"level":2,"text":"Investing in training the team will need to complete the project successfully is essential"},{"level":2,"text":"Allocate resources"},{"level":2,"text":"This involves assigning resources to discrete tasks and factoring in the various roles required for each activity"},{"level":2,"text":"Resource allocation includes project scheduling and workload management activities"},{"level":2,"text":"Workload Management"},{"level":2,"text":"Ensures that all resources are working at appropriate utilization levels"},{"level":1,"text":"The resource management process should be revisited as the project progresses to ensure that the team has access to the resources they need"},{"level":1,"text":"Successful resource management is critical to the success of a project"},{"level":2,"text":"Estimating necessary resources"},{"level":2,"text":"Securing resources"},{"level":2,"text":"Training team members"},{"level":2,"text":"Allocating resources to specific tasks"},{"level":2,"text":"Monitoring the project’s resources Managing Risk"}]},{"id":"g81","part":9,"title":"Managing Risk","blocks":[{"level":1,"text":"Every project is exposed to risks, and no plan can completely assure smooth progress"},{"level":1,"text":"Risks"},{"level":2,"text":"Unforeseen events that can either positively or negatively affect the project"},{"level":1,"text":"Risk, issue, and change management are interconnected processes in project management"},{"level":2,"text":"Risk management process involves identifying and establishing response plans for these risks"},{"level":2,"text":"Issues are current events that require immediate attention and recovery"},{"level":2,"text":"Changes refer to modifications in project scope, budget, or timeline that require adjustments in project activities or resources"},{"level":1,"text":"Risks can have both negative and positive impacts on the project"},{"level":1,"text":"When a documented risk materializes, it becomes an issue"},{"level":1,"text":"Project changes can also be triggered by issues"},{"level":1,"text":"The risk management process involves four main tasks"},{"level":2,"text":"Risk Identification"},{"level":2,"text":"Involves creating a comprehensive list of potential risks, refining the list, and maintaining it in a risk register"},{"level":2,"text":"Risk Analysis"},{"level":2,"text":"Assesses the likelihood and impact of each identified risk to prioritize them"},{"level":2,"text":"Risk Treatment"},{"level":2,"text":"Involves developing response plans for each identified risk"},{"level":2,"text":"Risk Monitoring"},{"level":2,"text":"Includes tracking progress on response plans and updating the risk register"},{"level":1,"text":"Qualitative Risk Analysis"},{"level":2,"text":"Subjective approach that relies on individual perception and interpretation of risks, using basic scales to evaluate them"},{"level":2,"text":"Two main considerations in qualitative analysis are interconnectivity and detectability"},{"level":1,"text":"Quantitative Risk Analysis"},{"level":2,"text":"Objective technique that uses verifiable data to assign scores to project risks"},{"level":2,"text":"These quantitative methods provide more accurate probability estimates and help prioritize and manage high-impact risks"},{"level":1,"text":"4 Strategies for Addressing Negative Risks"},{"level":2,"text":"Avoidance"},{"level":2,"text":"Mitigation"},{"level":2,"text":"Transfer"},{"level":2,"text":"Acceptance"},{"level":1,"text":"4 Strategies for Addressing Positive Risks"},{"level":2,"text":"Exploitation"},{"level":2,"text":"Enhancement"},{"level":2,"text":"Sharing"},{"level":2,"text":"Acceptance"},{"level":1,"text":"Risk Mitigation Plan"},{"level":2,"text":"Developed to minimize the impact of negative risks and maximize the benefits of positive risks"},{"level":1,"text":"Contingency Plan"},{"level":2,"text":"Also known as fallback or backup plans, are created to respond in case the risk occurs, enabling a rapid response and recovery"},{"level":1,"text":"A risk register is used to record project risks and includes essential fields"},{"level":2,"text":"Risk ID"},{"level":2,"text":"Description"},{"level":2,"text":"Analysis Summary"},{"level":2,"text":"Priority Scoring Criteria"},{"level":2,"text":"Owner"},{"level":2,"text":"Response"},{"level":1,"text":"Transition Plan"},{"level":2,"text":"Outline how the project team transfers ownership of the product to permanent owners"},{"level":1,"text":"Internal and external transition plans differ in formality and focus"},{"level":2,"text":"Internal plans can be more informal and use company-specific language, while external plans comply with contracts and exclude internal jargon"}]},{"id":"g82","part":9,"title":"Comparing Risk, Issues, and Changes","blocks":[{"level":1,"text":"Risk, issue, and change management are interrelated processes that require different approaches to create unique management plan"},{"level":1,"text":"Risks"},{"level":2,"text":"Potential future events that may or may not occur"},{"level":1,"text":"Issues"},{"level":2,"text":"Current events that require immediate attention and recovery"},{"level":1,"text":"Changes"},{"level":2,"text":"Modifications in project scope, budget, or timeline that require adjustments in project activities or resources"},{"level":1,"text":"Change control evaluates new change requests and tracks completed changes"},{"level":1,"text":"While risks typically have negative connotations, they can also have positive impacts on the project"},{"level":1,"text":"A comprehensive risk assessment can help a project prepare for potential issues"},{"level":1,"text":"Risk response planning may necessitate changes to the project plan, particularly if the risk's likelihood and impact are high"},{"level":1,"text":"Project changes can also be triggered by issues"},{"level":2,"text":"When an issue arises, it must be evaluated for priority and response, which could result in immediate remediation, no action, or a change to the project plan"}]},{"id":"g83","part":9,"title":"Risk Management Overview","blocks":[{"level":1,"text":"Risk management involves anticipating potential risks and developing proactive strategies to address them"},{"level":1,"text":"4 Main Tasks of Risk Management Process"},{"level":2,"text":"Identifying the risk"},{"level":2,"text":"Create a comprehensive list of all potential risks, drawing from past experience, the current environment, and other projects"},{"level":2,"text":"Analyzing the risk"},{"level":2,"text":"Assess the likelihood of each identified risk and its potential impact"},{"level":2,"text":"Treating the risk"},{"level":2,"text":"Develop a risk management strategy for each identified risk, assigning an owner and a response plan for each one"},{"level":2,"text":"Monitoring the risk"},{"level":2,"text":"Establish a plan to monitor the risks throughout the project, including tracking progress on response plans and tracking the occurrence of risk events"},{"level":1,"text":"By following this risk management process, prepare for potential risks and mitigate their impact"},{"level":1,"text":"Risk can be categorized as either known or unknown"},{"level":1,"text":"The purpose of a risk management assessment is to reduce the number of unknown risks"},{"level":1,"text":"By collecting and compiling inputs from everyone involved, the list of risks can be significantly expanded and the amount of unknown risk can be significantly reduced"},{"level":1,"text":"The risk management process shrinks the number of unknown risks, making for a resilient project"},{"level":1,"text":"It's impossible to eliminate all risk"},{"level":1,"text":"Some risk roles to consider"},{"level":2,"text":"Risk Owner"},{"level":2,"text":"The person responsible for managing a risk who creates plans for risk mitigation and response and is the first to be notified when a risk occurs"},{"level":2,"text":"Risk Manager"},{"level":2,"text":"Administers the risk register and leads the overall risk management process, including risk analysis and response"},{"level":2,"text":"Senior Management"},{"level":2,"text":"Responsible for managing organizational risks and may become stakeholders for specific risks in a project depending on their priority and nature"}]},{"id":"g84","part":9,"title":"Internal vs External Risk","blocks":[{"level":1,"text":"During the planning phase of the project, the PM holds a risk assessment meeting"},{"level":2,"text":"This session includes the project team, key stakeholders, SMEs, and the project sponsor"},{"level":2,"text":"The team will brainstorm all the items that could happen to the project— both good and bad"},{"level":2,"text":"The team will assess each risk to determine how likely it is to happen and how it would impact the project"},{"level":2,"text":"The team will create a plan for what they will do if each risk happens"},{"level":2,"text":"The team records all the risks and their responses in a risk register"},{"level":1,"text":"Difference between internal and external risk"},{"level":2,"text":"Internal Risk"},{"level":2,"text":"Originates within the organization"},{"level":2,"text":"Common internal risks include"},{"level":2,"text":"Projects"},{"level":2,"text":"One of the risks is the possibility of losing resources due to a new, higher-priority project approved by the company"},{"level":2,"text":"Digital Transformation"},{"level":2,"text":"Companies that invest in digital transformation usually evaluate their current technology stack and adopt modern products"},{"level":2,"text":"New Management"},{"level":2,"text":"A change in senior management can also affect project outcomes, as their priorities dictate the organization's operations and project portfolio"},{"level":2,"text":"Reorganization"},{"level":2,"text":"A reorganization is another risk for projects, where changes in reporting structures, job titles, stakeholders, and project sponsors may affect the team's dynamics and project progress"},{"level":2,"text":"Merger and Acquisition"},{"level":2,"text":"It can introduce new risks, such as differences in company culture, work styles, processes, and technology stacks"},{"level":2,"text":"External Risk"},{"level":2,"text":"Originates outside the organization"},{"level":2,"text":"Common external risks include"},{"level":2,"text":"Infrastructure End-Of-Life (EOL)"},{"level":2,"text":"A technology or product is no longer supported or maintained by the vendor"},{"level":2,"text":"Cybersecurity Incidents"},{"level":2,"text":"These occur when unauthorized parties gain access to an organization's computer systems, resulting in the theft, modification, or seizure of data"},{"level":2,"text":"Regulatory Environment Changes"},{"level":2,"text":"Compliance failures can result in significant adverse impacts, including fines, remediation plans, reinspection, or even shutdown orders"}]},{"id":"g85","part":9,"title":"Qualitative Risk Analysis","blocks":[{"level":1,"text":"Qualitative Risk Analysis is a subjective approach that relies on individual perception and interpretation of risks"},{"level":1,"text":"There are two main considerations when discussing qualitative risk analysis"},{"level":2,"text":"Interconnectivity"},{"level":2,"text":"Refers to how risk can have a wider impact beyond a single event"},{"level":2,"text":"Analyzing interconnectivity involves assessing how project risks may interact with one another"},{"level":2,"text":"Detectability"},{"level":2,"text":"An essential measure of how quickly a risk can be identified if it were to materialize"},{"level":2,"text":"Detectability can affect the scope and impact of a risk event"},{"level":2,"text":"Low-detectability risks can be unnoticed and discovered after reaching the end-users"},{"level":1,"text":"Qualitative analysis can be assigned quantitative values"}]},{"id":"g86","part":9,"title":"Quantitative Risk Analysis","blocks":[{"level":1,"text":"Quantitative Risk Analysis is an objective technique that employs verifiable data to assign scores to project risks"},{"level":1,"text":"Probability Distribution"},{"level":2,"text":"A way of describing how likely each possible outcome"},{"level":2,"text":"Single average only scratches the surface of the true complexity of a distribution"},{"level":1,"text":"Simulations provide reliable probability estimates for high-impact risks"},{"level":1,"text":"It's important to remember that the accuracy of the simulation depends on the quality of data entered"},{"level":1,"text":"The most common measures of risk are probability and impact"},{"level":1,"text":"Probability"},{"level":2,"text":"Measures the likelihood of a risk occurring and can be represented on a numerical or relative scale"},{"level":2,"text":"Numerical scale typically ranges from 0 to 1, with 1 representing a 100% chance of occurrence"},{"level":2,"text":"Most probability scales exclude 0 and 1"},{"level":1,"text":"Impact"},{"level":2,"text":"Measures how a risk would affect the business if it were to occur and can be represented on a numerical or relative scale"},{"level":2,"text":"A multidimensional impact assessment can be used to measure how the risk affects various business measures, such as cost, time, or scope"},{"level":1,"text":"Probability and impact are usually measured together to form a matrix or quadrant scale"},{"level":1,"text":"A probability impact assessment is a good starting point for risk analysis"},{"level":1,"text":"Failure Mode and Effect Analysis (FMEA)"},{"level":2,"text":"A detailed analysis of a single process to identify multiple risks"},{"level":2,"text":"FMEAs can proactively identify and eliminate design flaws during product and process design"},{"level":2,"text":"It is a living document that requires a fair amount of time and analysis to maintain as the process changes"},{"level":1,"text":"Scenario Analysis"},{"level":2,"text":"Also known as situational analysis or what-if analysis, is a process that involves generating potential events and assessing their impact"},{"level":2,"text":"Particularly useful for assessing low-probability, high-impact events, such as natural disasters or ransomware attacks"},{"level":2,"text":"The process of scenario analysis involves asking what-if questions"},{"level":2,"text":"For example"},{"level":2,"text":"What happens to Y if I change X?"},{"level":2,"text":"If X happens, how will it impact Y?"},{"level":2,"text":"How does a change in X affect Y?"},{"level":2,"text":"Scenario analysis is a valuable tool that can help individuals and organizations prepare for unexpected events and make informed decisions about risk management"}]},{"id":"g87","part":9,"title":"Risk Management Strategies","blocks":[{"level":1,"text":"Risk management identifies the risks and optimizes the impact"},{"level":1,"text":"The risk management strategy outlines how to address each risk in the event it occurs, also referred to as \"risk response\" or \"risk treatment”"},{"level":1,"text":"4 Strategies for Addressing Negative Risks"},{"level":2,"text":"Risk Avoidance"},{"level":2,"text":"Prevents a risk from occurring by avoiding anything that could cause the event"},{"level":2,"text":"Risk Mitigation"},{"level":2,"text":"Aims to reduce the impact or likelihood of a risk"},{"level":2,"text":"Risk Transfer"},{"level":2,"text":"Assigns the risk to a third party, shifting financial responsibility for the risk to someone else"},{"level":2,"text":"Risk Acceptance"},{"level":2,"text":"A “do nothing” approach that accepts the consequences of a risk if it were to occur"},{"level":1,"text":"4 Strategies for Addressing Positive Risks"},{"level":2,"text":"Risk Exploitation"},{"level":2,"text":"Taking steps to ensure that the event occurs"},{"level":2,"text":"Risk Enhancement"},{"level":2,"text":"Maximizes the positive impact of a risk"},{"level":2,"text":"Risk Sharing"},{"level":2,"text":"Finds others who would benefit from the risk and share it"},{"level":2,"text":"Risk Acceptance"},{"level":2,"text":"A “do nothing” approach where you enjoy the benefits if the risk occurs and receive no benefits if it doesn’t"}]},{"id":"g88","part":9,"title":"Mitigation and Contingency Plans","blocks":[{"level":1,"text":"Once a risk has been analyzed and a treatment option has been selected, the risk owner develops a mitigation plan that is implemented prior to the occurrence of the risk"},{"level":2,"text":"Risk mitigation plan minimizes the impact of negative risks and maximize the benefits of positive risks"},{"level":2,"text":"Despite the name \"mitigation,\" this plan is applicable to any risk response strategy"},{"level":1,"text":"Once a risk treatment has been chosen, the risk owner creates a contingency plan, also known as a fallback or backup plan"},{"level":1,"text":"Contingency Plan"},{"level":2,"text":"Outlines how to respond in case the risk occurs"},{"level":2,"text":"A contingency plan should include, at minimum, the following information"},{"level":2,"text":"The trigger that signals that the risk has occurred"},{"level":2,"text":"Immediate response processes"},{"level":2,"text":"Timed or phased responses, including immediate reaction, follow- up, and recovery phases"},{"level":2,"text":"Communication details, such as primary contacts, who to inform, and escalation procedures"},{"level":2,"text":"Contingency plan is necessary for each high-priority risk"},{"level":1,"text":"The risk management process gathers all necessary risk information, which is then compiled in a risk register"},{"level":2,"text":"The risk register contains several essential fields"},{"level":2,"text":"Risk ID"},{"level":2,"text":"Risk Description"},{"level":2,"text":"Risk Analysis Summary"},{"level":2,"text":"Impact or Priority Scoring Criteria"},{"level":2,"text":"Risk Priority or Ranking"},{"level":2,"text":"Risk Owner"},{"level":2,"text":"Risk Response or Treatment"},{"level":2,"text":"Risk register is first created and populated during the initial risk assessment"},{"level":2,"text":"Updating the register is crucial when the probability or impact of a risk changes so that resources can focus on higher-priority items"},{"level":1,"text":"Risk Report"},{"level":2,"text":"Shares pertinent information about the project's risk management process and shared throughout the project's remaining duration"},{"level":2,"text":"The risk report should include the following summary"},{"level":2,"text":"Current status of project risks"},{"level":2,"text":"Total number of identified risks"},{"level":2,"text":"Trends"},{"level":2,"text":"Summary of realized risks"},{"level":2,"text":"Financial, timeline, and scope impacts resulting from realized risks"},{"level":2,"text":"Notable emerging risks"},{"level":2,"text":"Notable risks that are high-impact and time-sensitive"},{"level":2,"text":"Forecasted risk status"},{"level":2,"text":"Risk reporting summarizes the project's risk status and how it impacts the project"},{"level":1,"text":"The PM begins by creating a risk management plan that outlines the approach and tools to be used in the risk management process"},{"level":2,"text":"Risk identification plan should be included and detail how the team will identify risks"},{"level":2,"text":"Risk Breakdown Structure (RBS) should be created to classify the nature of risks by category"},{"level":2,"text":"Risk response strategy should summarize the options used to manage risks"},{"level":2,"text":"Financial factors, such as funding availability, funding needs, or resource requirements, should be listed"},{"level":2,"text":"Risk monitoring plan should describe how the PM and risk owners will identify and track risks"},{"level":2,"text":"Outline the timing of all risk management activities"},{"level":2,"text":"Initial risk assessment meeting"},{"level":2,"text":"Ongoing risk reporting"},{"level":2,"text":"Other recurring activities"}]},{"id":"g89","part":9,"title":"Transition Plans","blocks":[{"level":1,"text":"Transition Plan"},{"level":2,"text":"Outlines how the project team will transfer ownership of the product to permanent owners at the end of the project"},{"level":2,"text":"It also allows the team to schedule transition activities into the project timeline"},{"level":1,"text":"After the project is completed, the product enters a maintenance phase"},{"level":1,"text":"Operations team then takes over the maintenance phase, which involves routine support, updates, and process improvement"},{"level":1,"text":"A transition plan can take the form of a checklist or a detailed document"},{"level":2,"text":"Key elements to include in the plan"},{"level":2,"text":"Roles and Responsibilities"},{"level":2,"text":"Define who is responsible for completing the transition activities, who will own the maintenance activities, and who will be in charge of the transition plan"},{"level":2,"text":"Transition Schedule"},{"level":2,"text":"Define the schedule of transition activities, including the official end date of the project and the go-live date"},{"level":2,"text":"Maintenance Schedule"},{"level":2,"text":"Identify the ongoing maintenance requirements and schedule of activities that the operations team will need to include in their work"},{"level":2,"text":"Training"},{"level":2,"text":"Identify the operational training requirements and delivery channels needed to train the maintenance team, including computer-based training or expert-led training sessions"},{"level":2,"text":"Activities"},{"level":2,"text":"List all the other tasks required to complete the handoff, including access setup, asset turnover, and review sessions"},{"level":2,"text":"Tools and Techniques"},{"level":2,"text":"List any specific tools, techniques, or processes the operations team will need long term"},{"level":2,"text":"Product Documentation"},{"level":2,"text":"Code documentation, product specifications, configurations, and access and credentials"},{"level":2,"text":"Asset Turnover Plan"},{"level":2,"text":"Create a strategy for how and when assets will move from the project team to the maintenance team"},{"level":2,"text":"Impact Analysis"},{"level":2,"text":"Identify how the successful implementation of the project will change the work"},{"level":1,"text":"During the go-live phase, the project team leads the efforts while keeping the operations team informed"},{"level":1,"text":"Explicitly identifying the operational handoff in the project schedule is essential"},{"level":1,"text":"Transition plans are created for both internal and external audiences"},{"level":1,"text":"Internal transition plans can be formal or informal, depending on the organization's procedures"},{"level":1,"text":"External transition plans are typically more formal than internal plans"},{"level":1,"text":"In some cases, a project handoff may involve switching vendors Creating a Project Schedule"}]},{"id":"g90","part":10,"title":"Creating a Project Schedule","blocks":[{"level":1,"text":"Estimating costs, identifying resources, and planning a sequence can make a project appear overwhelming"},{"level":1,"text":"Waterfall projects utilize a Work Breakdown Structure (WBS) for this purpose, while agile projects employ a project backlog"},{"level":2,"text":"The level of detail required for breaking down a project depends on the specific project and team"},{"level":1,"text":"Agile teams aim to create a potentially releasable product in fixed increments of time called sprint"},{"level":1,"text":"The sprint goal signifies project progress and is within the control of the development team"},{"level":1,"text":"The cadence determines the size of work items and the frequency of plan adjustments"},{"level":1,"text":"When creating a Work Breakdown Structure (WBS), there are several key components and design guidelines to consider"},{"level":2,"text":"Elements are the deliverables in the WBS, represented by boxes or rows, while work packages are the lowest elements without child elements and represent outcomes-based work"},{"level":2,"text":"Levels indicate the layer of the WBS where an element resides, and numbering schemes assign a number to each element based on its hierarchy"},{"level":2,"text":"Legs and branches refer to groups of elements with shared ancestors and multiple elements that do not represent the entire top-level element, respectively"},{"level":1,"text":"The backlog serves as the body of work that a team will complete, and it is continuously refined and modified by the backlog owner"},{"level":1,"text":"Backlogs are particularly useful for projects with many unknowns, as they provide flexibility within fixed boundaries to avoid scope creep"},{"level":1,"text":"Key differences between WBS and project backlog"},{"level":2,"text":"WBS"},{"level":2,"text":"Controls scope, time, and cost"},{"level":2,"text":"Details are stored in a WBS dictionary"},{"level":2,"text":"Assumes that all scope items will be delivered"},{"level":2,"text":"Backlog (Agile)"},{"level":2,"text":"Prioritizes flexibility while fixing time and cost"},{"level":2,"text":"Details are contained within backlog items"},{"level":2,"text":"Works on one deliverable set at a time"},{"level":1,"text":"Project Tasks"},{"level":2,"text":"Specific actions taken to complete deliverables and are not always necessary to document in detail"},{"level":1,"text":"Dependencies play a crucial role in sequencing project activities"},{"level":2,"text":"4 Types of Dependencies"},{"level":2,"text":"Finish-to-Start (FS)"},{"level":2,"text":"Start-to-Start (SS)"},{"level":2,"text":"Finish-to-Finish (FF)"},{"level":2,"text":"Start-to-Finish (SF)"},{"level":1,"text":"Estimation techniques are essential for forecasting the time, resources, and cost requirements of a project"},{"level":2,"text":"Top-Down Estimating"},{"level":2,"text":"Technique that starts with estimating the total project cost or duration and then breaks it down into smaller components"},{"level":2,"text":"Bottom-Up Estimating"},{"level":2,"text":"Involves estimating the individual components and then aggregating them to determine the overall project cost or duration"},{"level":2,"text":"Analogous Estimating"},{"level":2,"text":"Uses historical data from similar past projects to estimate the current project's cost or duration"},{"level":2,"text":"Parametric Estimating"},{"level":2,"text":"Applies statistical relationships between variables and parameters to estimate project characteristics"},{"level":2,"text":"Three-Point Estimating"},{"level":2,"text":"Considers the most likely, optimistic, and pessimistic estimates to calculate a weighted average estimate"},{"level":2,"text":"Expert Judgment"},{"level":2,"text":"Relies on the knowledge and experience of experts to estimate project parameters"}]},{"id":"g91","part":10,"title":"Milestones","blocks":[{"level":1,"text":"The first step in creating a project schedule is to break down these large work items into smaller, estimable pieces"},{"level":1,"text":"Decision-making guidelines can assist in identifying the appropriate level of detail for any project"},{"level":1,"text":"Project Milestones"},{"level":2,"text":"Represent critical checkpoints in a project and have a duration of zero days and are typically denoted by a diamond on graphic project schedules"},{"level":1,"text":"As a PM, it is crucial to ensure that the project schedule is aggressive yet achievable to keep the team productive"},{"level":1,"text":"Measuring progress against each milestone helps identify scheduling issues early"},{"level":1,"text":"Stakeholders not involved in the project's daily operations require regular updates but don't need to know about every minor decision"},{"level":1,"text":"Common Project Milestones"},{"level":2,"text":"Project Approval"},{"level":2,"text":"Project Kickoff"},{"level":2,"text":"Solution Design Approval"},{"level":2,"text":"Project Schedule Approval"},{"level":2,"text":"Project Phase Transition"},{"level":2,"text":"Sprint Demos"},{"level":2,"text":"Release"},{"level":2,"text":"Any Approval Events"},{"level":2,"text":"Sprint Goals"},{"level":1,"text":"In an agile team, the goal is to create a potentially releasable product every fixed increment of time, called a sprint, which can last from 1 to 4 weeks"},{"level":1,"text":"To ensure alignment between sprint goals, project activities, and milestones, work closely with the product owner and development team throughout the project"},{"level":1,"text":"Consider the following steps to identify milestones for your project"},{"level":2,"text":"Identify common project milestones such as project approval, kickoff, and schedule approval"},{"level":2,"text":"Determine the expected milestones for your project methodology"},{"level":2,"text":"Work with the team and functional experts to identify critical events specific to the project"},{"level":2,"text":"Identify any formal approval events"},{"level":2,"text":"Review the milestone schedule to ensure the frequency and pace are reasonable"},{"level":2,"text":"Adjust the milestones upon learning"},{"level":1,"text":"A good starting point is to have a milestone about once a month"}]},{"id":"g92","part":10,"title":"Project Cadence","blocks":[{"level":1,"text":"Project Cadence"},{"level":2,"text":"Determines the frequency and structure of recurring events within a project"},{"level":2,"text":"Sprint Duration"},{"level":2,"text":"Regular Team Meeting"},{"level":2,"text":"Stakeholder Review"},{"level":1,"text":"Establishing an appropriate pace, or cadence, for a project"},{"level":1,"text":"Cadence refers to the rhythm and frequency of recurring events in a project, such as team meetings, stakeholder reviews, and sprint lengths"},{"level":1,"text":"Cadence also affects the size of work items"},{"level":1,"text":"Setting the cadence early in the planning process is crucial to ensure that the work items are appropriately sized and the project progresses smoothly"},{"level":1,"text":"Cadence should reflect how often the plan should change"},{"level":1,"text":"A project may have multiple cadences reflected in its schedule, milestones, and communication plan"}]},{"id":"g93","part":10,"title":"Work Breakdown Structure","blocks":[{"level":1,"text":"Work Breakdown Structure (WBS)"},{"level":2,"text":"An essential component of project management and informs other project documents, including the project schedule"},{"level":1,"text":"Task"},{"level":2,"text":"An action completed to deliver project work"},{"level":1,"text":"Activity"},{"level":2,"text":"Any work related to the project"},{"level":1,"text":"Work"},{"level":2,"text":"The result of doing something, not the act of doing something"},{"level":1,"text":"Schedule"},{"level":2,"text":"Contains the WBS deliverables, timing, and resource requirements"},{"level":1,"text":"Deliverable"},{"level":2,"text":"The outcomes of the project"},{"level":1,"text":"Key Components of WBS"},{"level":2,"text":"Element"},{"level":2,"text":"The deliverables in a WBS"},{"level":2,"text":"The elements of a WBS include nouns only"},{"level":2,"text":"Work Package/Terminal Element"},{"level":2,"text":"Lowest element in each branch or leg (an element without a child element is a work package)"},{"level":2,"text":"Work packages are an outcome-based element of work and not a task"},{"level":2,"text":"Level"},{"level":2,"text":"The layer of the WBS where an element resides"},{"level":2,"text":"Numbering Scheme/Code of Accounts"},{"level":2,"text":"Element that are assigned a number according to its place in the hierarchy"},{"level":2,"text":"Leg"},{"level":2,"text":"A group of elements with a shared ancestor"},{"level":2,"text":"Branch"},{"level":2,"text":"One or more elements that do not represent the whole top-level element in the branch"},{"level":1,"text":"Design Guidelines of WBS"},{"level":2,"text":"Mutually Exclusive Collectively Exhaustive (MECE)"},{"level":2,"text":"An organization and problem-solving method"},{"level":2,"text":"MECE is challenging to design, but it helps ensure accountability for a project"},{"level":2,"text":"The 100% Rule"},{"level":2,"text":"Indicates 100% coverage of the project work without including anything beyond the project's deliverables and project management work"},{"level":1,"text":"While planning a WBS, include only outcomes instead of tasks"},{"level":1,"text":"In most projects, it is recommended to use four levels or fewer"},{"level":2,"text":"Work elements can be broken down until they meet the following criteria"},{"level":2,"text":"The team can estimate the time, cost, and resources required for the work package"},{"level":2,"text":"The work element is expected to last for the 8/80 rule"},{"level":2,"text":"The element produces a measurable deliverable"},{"level":2,"text":"Breaking the element further would not help the project"}]},{"id":"g94","part":10,"title":"Creating the WBS","blocks":[{"level":1,"text":"Work Breakdown Structure (WBS)"},{"level":2,"text":"Project management tool that provides a visual representation of a project's scope, tasks, and deliverables"},{"level":1,"text":"A WBS also helps to identify project risks, estimate project timelines and costs, and allocate resources effectively"},{"level":1,"text":"To create a WBS, you need to follow six basic steps"},{"level":2,"text":"Determine the scope"},{"level":2,"text":"Understand the project's objectives, constraints, requirements, and identify the stakeholders and their expectations"},{"level":2,"text":"To determine the scope, use the following techniques"},{"level":2,"text":"Brainstorming"},{"level":2,"text":"Mind Mapping"},{"level":2,"text":"Interviewing Stakeholders"},{"level":2,"text":"Identify Deliverables"},{"level":2,"text":"Deliverables are the tangible and intangible products or services that the project will produce, and can include reports, software, hardware, training materials, and more"},{"level":2,"text":"To identify the deliverables, use the following techniques"},{"level":2,"text":"Decomposition"},{"level":2,"text":"Process Mapping"},{"level":2,"text":"Flowcharting"},{"level":2,"text":"Identify Team Members"},{"level":2,"text":"Consider the skills, knowledge, and experience required for each task and allocate team members accordingly"},{"level":2,"text":"To identify team members, you can use a Responsibility Matrix or RACI Chart"},{"level":2,"text":"Build Level 2"},{"level":2,"text":"Provide more detail about each deliverable and include all the tasks required to complete each one"},{"level":2,"text":"To build Level 2, you can use techniques such as"},{"level":2,"text":"Brainstorming"},{"level":2,"text":"Mind Mapping"},{"level":2,"text":"Decomposition"},{"level":2,"text":"Build the Remaining Levels"},{"level":2,"text":"Provide more detail about each task required to complete each deliverable"},{"level":2,"text":"To build the remaining levels, you can use the same techniques as Level 2, such as brainstorming, mind mapping, or decomposition"},{"level":2,"text":"Document each level in a hierarchical structure, starting with the highest-level deliverables and breaking them down into smaller components"},{"level":2,"text":"Create the WBS Dictionary"},{"level":2,"text":"Provides additional details that cannot be accommodated on the WBS diagram"},{"level":2,"text":"A WBS dictionary is customizable, and it should include the following elements"},{"level":2,"text":"Work Package ID"},{"level":2,"text":"Work Package Name"},{"level":2,"text":"Work Package Description"},{"level":2,"text":"Assigned to"},{"level":2,"text":"Date of Assignment"},{"level":2,"text":"Due Date"},{"level":2,"text":"Estimated Cost"},{"level":1,"text":"By creating a WBS, a project manager can assign resources and set timelines for each level of the project, ensuring that the project progresses smoothly and on schedule"}]},{"id":"g95","part":10,"title":"Project and Product Backlog","blocks":[{"level":1,"text":"A project backlog and a product backlog are not identical"},{"level":1,"text":"WBS and the project backlog focus on creating deliverables and aim to leave execution details to the team"},{"level":1,"text":"WBS and the project backlog employ a hierarchical structure that breaks down large projects into smaller pieces of work"},{"level":1,"text":"WBS details are stored in a WBS dictionary, while product backlog details are contained within backlog items"},{"level":1,"text":"WBS is more structured in design, while backlogs do not have design requirements"},{"level":1,"text":"WBS operates under fixed scope, time, and cost, while project backlog utilizes agile ceremonies to fix time and cost, and the scope of work remains flexible"},{"level":1,"text":"WBS project schedule assumes that all scope items will be delivered, while a backlog schedule assumes that some items may not be delivered"},{"level":1,"text":"Value is not assumed in project backlogs"},{"level":1,"text":"A WBS and a project backlog require breaking work down into manageable pieces"},{"level":1,"text":"Epic"},{"level":2,"text":"A large deliverable that is triggered by a business case and is equivalent to level 1 of a WBS"},{"level":1,"text":"Feature"},{"level":2,"text":"Smaller than an epic and lasts 1-3 iterations"},{"level":1,"text":"User Story"},{"level":2,"text":"The smallest agile deliverable, equivalent to a work package in size and spirit"},{"level":1,"text":"Epics, features, and user stories are deliverable-based products that use nouns"},{"level":1,"text":"WBS and a product backlog define what the team needs to deliver"}]});
